    fbits = req['fbits']
    mode = req['mode']
    pairs = req['pairs']

    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits                # 2**fbits
    Eall = (1 << ebits) - 1       # all-ones exponent
    emin = 1 - bias
    emax = Eall - 1 - bias
    fmask = F - 1
    spos = ebits + fbits          # index of sign bit
    topf = F >> 1                 # top fraction bit (quiet bit)

    CANON_NAN = (Eall << fbits) | topf
    MAX_FIN = ((Eall - 1) << fbits) | fmask

    invalid = False
    any_nan = False
    inf_pos = False               # a positive infinite product exists
    inf_neg = False               # a negative infinite product exists

    prods = []                    # nonzero finite products: (sign, mantissa, exp2)
    any_product = False           # at least one finite (non-NaN, non-inf) pair
    all_neg_zero = True           # every product so far is a negative signed zero

    for pair in pairs:
        va = int(pair[0], 16)
        vb = int(pair[1], 16)
        sa = (va >> spos) & 1
        ea = (va >> fbits) & Eall
        fa = va & fmask
        sb = (vb >> spos) & 1
        eb = (vb >> fbits) & Eall
        fb = vb & fmask

        a_nan = ea == Eall and fa != 0
        b_nan = eb == Eall and fb != 0
        # signaling NaN: exponent all ones, nonzero fraction, top fraction bit 0
        if (a_nan and not (fa & topf)) or (b_nan and not (fb & topf)):
            invalid = True
        if a_nan or b_nan:
            any_nan = True
            continue

        a_inf = ea == Eall
        b_inf = eb == Eall
        a_zero = ea == 0 and fa == 0
        b_zero = eb == 0 and fb == 0

        if (a_inf and b_zero) or (b_inf and a_zero):
            invalid = True
            continue

        ps = sa ^ sb
        if a_inf or b_inf:
            if ps:
                inf_neg = True
            else:
                inf_pos = True
            continue

        # finite x finite
        any_product = True
        if ea == 0:
            Ma, Ea = fa, emin - fbits
        else:
            Ma, Ea = F + fa, ea - bias - fbits
        if eb == 0:
            Mb, Eb = fb, emin - fbits
        else:
            Mb, Eb = F + fb, eb - bias - fbits
        M = Ma * Mb
