        s = 1 if inf_neg else 0
        return {'bits': format((s << spos) | (Eall << fbits), 'x'), 'flags': []}

    # ---- exact finite sum ----
    total = 0
    cur_exp = 0
    for ps, M, E in prods:
        if E < cur_exp:
            total <<= (cur_exp - E)
            cur_exp = E
        term = M << (E - cur_exp)
        total = total - term if ps else total + term
    # exact sum == total * 2**cur_exp

    if total == 0:
        neg = (any_product and all_neg_zero) or mode == 'RDN'
        bits = (1 << spos) if neg else 0
        return {'bits': format(bits, 'x'), 'flags': []}

