            if twice > den or (twice == den and (quo & 1)):
                quo += 1
        elif mode == 'RNA':
            if (rem << 1) >= den:
                quo += 1
        elif mode == 'RUP':
            if s == 0:
                quo += 1
        elif mode == 'RDN':
            if s == 1:
                quo += 1
        # RTZ: truncate
    n = quo                                  # rounded magnitude y = n * 2**q_exp

    if n == 0:
        # nonzero x rounded to zero: keep exact sign; y=0 < 2**emin and inexact
        return {'bits': format(s << spos, 'x'),
                'flags': ['underflow', 'inexact']}

